// Also check by product_id from the items
if (items.length > 0) {
    for (const item of items) {
        const prodWarranties = db.prepare(\"SELECT * FROM warranties WHERE product_id = ?\").all(item.product_id);
        console.log('\nWarranties for product ' + item.product_id + ':', JSON.stringify(prodWarranties, null, 2));
    }
