node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Start a transaction for atomicity
const cancel = db.transaction(() => {
  // 1. Update ITEM-E5801A status to cancelled + record refund details on the item
  const itemUpdate = db.prepare(\`
    UPDATE order_items 
    SET item_status = 'cancelled',
        refund_amount = 88.00,
        refund_method = 'cc_21e6eed2'
    WHERE oi_id = 'ITEM-E5801A' AND order_id = 'ORD-E0E671'
  \`);
  const itemResult = itemUpdate.run();
  console.log('Item update — rows changed:', itemResult.changes);

  // 2. Insert refund record into order_payments
  const paymentInsert = db.prepare(\`
    INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id)
    VALUES ('ORD-E0E671', 'refund', 88.00, 'cc_21e6eed2')
  \`);
  const payResult = paymentInsert.run();
  console.log('Refund payment record inserted, id:', payResult.lastInsertRowid);

  // 3. Update order-level cancel_reason for traceability
  const orderUpdate = db.prepare(\`
    UPDATE orders
    SET cancel_reason = 'Partial cancellation: ITEM-E5801A cancelled pre-shipment'
    WHERE order_id = 'ORD-E0E671'
  \`);
  const orderResult = orderUpdate.run();
  console.log('Order update — rows changed:', orderResult.changes);
});

cancel();

// Verify the changes
console.log('\n--- Verification ---');
const item = db.prepare(\"SELECT oi_id, name, item_status, refund_amount, refund_method FROM order_items WHERE oi_id = 'ITEM-E5801A'\").get();
console.log('Item after cancel:', JSON.stringify(item, null, 2));

const refund = db.prepare(\"SELECT * FROM order_payments WHERE order_id = 'ORD-E0E671'\").all();
console.log('Payment records:', JSON.stringify(refund, null, 2));

const order = db.prepare(\"SELECT order_id, status, cancel_reason FROM orders WHERE order_id = 'ORD-E0E671'\").get();
console.log('Order after cancel:', JSON.stringify(order, null, 2));

const remainingItems = db.prepare(\"SELECT oi_id, name, item_status, unit_price FROM order_items WHERE order_id = 'ORD-E0E671'\").all();
console.log('All items in order:', JSON.stringify(remainingItems, null, 2));
"

